contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address caller, address recipient) public payable {
        require(address(this).balance >= 0);

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address actualOwner = c.owner();
        assert(reverted == (address(this) != actualOwner));
    }
}
